# Medical, Obstetrics and Gynecology (NREMT AEMT test plan: 25% to 29%).
# AEMT scope (2019 Scope of Practice Model): IV and IO access, IV dextrose, glucagon,
# naloxone, epinephrine, antiemetic and analgesia per protocol (footnote 5), inhaled nitrous
# oxide, epinephrine for anaphylaxis, auto-injector antidotes. Magnesium, benzodiazepines,
# amiodarone and adenosine are paramedic drugs and appear only as wrong options.
# Figures: NASEMSO National Model EMS Clinical Guidelines v3.0 (2022): Hypoglycemia, Opioid
# Poisoning, Anaphylaxis, Shock, Stroke, Childbirth, Neonatal Resuscitation, Bites and
# Envenomation, Agitated or Violent Patient, Pain Management.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Hypoglycemia", "An unresponsive adult has a glucose of 44 mg/dL and an IV line. What should you give?",
      ["D10 in small doses, up to 25 g", "Oral glucose gel in the cheek", "One full liter of saline first", "Glucagon IV push, then oral glucose"],
      "NASEMSO treats glucose of 60 mg/dL or less with IV dextrose given in increments, D10 preferred, to a field maximum of 25 g. Oral glucose needs a patient who can protect the airway, and glucagon is the option when no IV is possible."),
    N(1, 2, "Dextrose volume", "How many mL of 10 percent dextrose contain 25 g of dextrose?",
      250,
      "D10 holds 10 g in every 100 mL, so 25 g takes 250 mL. The same 25 g is 50 mL of D50 or 100 mL of D25."),
    S(1, 2, "Glucagon", "A 15 kg child with low blood sugar has no IV access. What glucagon dose fits?",
      ["0.5 mg", "1 mg", "2 mg", "3 mg"],
      "NASEMSO gives 0.5 mg IM or IN to children under 20 kg (or under 5 years) and 1 mg to those 20 kg or more. 3 mg is the dry-powder nasal product's dose, not an IM dose for a small child."),
    S(1, 1, "Oral glucose", "Oral glucose should not be given to a diabetic patient who:",
      ["Cannot swallow on command", "Has a glucose of 55 mg/dL", "Is confused but talking", "Takes insulin by pump"],
      "Oral glucose is for a conscious patient with a patent airway who can swallow. A low reading, mild confusion or an insulin pump do not stop it; a patient who cannot swallow may aspirate."),
    S(1, 2, "Opioid overdose", "A man with pinpoint pupils is breathing 4 times a minute and is blue. What comes first?",
      ["Ventilate him with a BVM", "Give IN naloxone, then wait", "Check a blood glucose", "Place him in recovery position"],
      "NASEMSO puts airway and breathing support before naloxone: oxygenate with a BVM, then give naloxone. Waiting for the drug to work leaves him hypoxic, and a glucose check comes after ventilation."),
    S(1, 2, "Naloxone", "When titrating IV naloxone for an opioid overdose, what is the goal?",
      ["Adequate breathing", "Full alertness", "Pupils that are wide", "A heart rate over 100"],
      "Naloxone is given to restore breathing, not to wake the patient completely. Large doses that wake him fully can bring on sudden withdrawal, vomiting and agitation."),
    M(1, 1, "Stroke recognition", "Which findings suggest an acute stroke? Select three.",
      ["One side of the face droops", "One arm drifts down", "Words come out slurred", "Muscle cramps in both legs", "Fever and a stiff neck", "Hiccups for an hour"],
      "Sudden facial droop, arm drift and slurred speech are the core stroke screen findings. Bilateral cramps, fever with a stiff neck and hiccups point elsewhere."),
    S(1, 2, "Stroke history", "For a suspected stroke, which time matters most to report?",
      ["When last known well", "When the family found her", "When you arrived on scene", "When she last ate a meal"],
      "Treatment windows are measured from the last time the patient was known to be normal. Time found can be hours later and would falsely shorten or lengthen the window."),
    S(1, 2, "Stroke mimics", "Before calling a stroke alert, which test should you do on scene?",
      ["Blood glucose", "Body temperature", "Pupil size", "Pulse oximetry only"],
      "Low blood sugar can cause one-sided weakness and slurred speech that clears with dextrose, so NASEMSO checks glucose in every suspected stroke."),
    S(1, 2, "Anaphylaxis", "An 18 kg child is wheezing with hives and vomiting after eating cashews. What IM epinephrine dose fits?",
      ["0.15 mg", "0.3 mg", "0.5 mg", "1 mg"],
      "NASEMSO gives 0.15 mg of 1 mg/mL epinephrine IM in the thigh to children under 25 kg and 0.3 mg to patients 25 kg or more."),
    S(1, 2, "Repeat epinephrine", "Signs of anaphylaxis persist after the first IM epinephrine dose. When can it be repeated?",
      ["After 5 to 15 minutes", "Not within 1 hour", "Only after a fluid bolus", "Every minute until improved"],
      "IM epinephrine may be repeated every 5 to 15 minutes while signs of anaphylaxis and poor perfusion persist, alongside a 20 mL/kg fluid bolus if perfusion is poor."),
    X(1, 2, "Anaphylaxis versus allergy", "For each patient, specify whether the findings fit anaphylaxis or a simple allergic reaction.",
      ["Hives only after a new soap", "Hives and wheezing after a sting", "Lip swelling and vomiting after peanuts", "Itchy eyes and sneezing in spring", "BP 78/40 after a bee sting"],
      ["Anaphylaxis", "Simple allergic reaction"], [1, 0, 0, 1, 0],
      "Anaphylaxis involves two or more body systems, or low blood pressure after exposure. Hives alone or itchy eyes and sneezing involve one system and are a simple allergic reaction."),
    S(1, 3, "Sepsis", "An adult with suspected sepsis has a MAP of 58. How does NASEMSO guide the fluids?",
      ["Boluses toward a MAP of 65", "A slow rate of 100 mL per hour", "Fluids only if SBP falls below 70", "Boluses to a MAP of 100"],
      "Adults in septic shock get rapid boluses, such as 500 mL, toward a MAP of 65, up to about 30 mL/kg unless pulmonary edema develops. Waiting for a lower pressure delays care, and a MAP of 100 is not the goal."),
    M(1, 2, "Sepsis recognition", "An older adult has a fever. Which findings raise concern for sepsis? Select three.",
      ["Breathing 26 a minute", "New confusion", "SBP of 86", "SpO2 of 98 percent", "Heart rate of 78", "Glucose of 112"],
      "A fast respiratory rate, new confusion and low blood pressure are signs that an infection is affecting the whole body. A normal saturation, heart rate and glucose do not add to the concern."),
    S(1, 2, "Status epilepticus", "A seizure that continues without stopping is status epilepticus once it has lasted about:",
      ["5 minutes", "1 minute", "15 minutes", "30 minutes"],
      "NASEMSO treats seizure activity lasting more than 5 minutes, or seizures without recovery between them, as needing active treatment. Waiting 15 or 30 minutes risks brain injury; benzodiazepines are given by ALS."),
    S(1, 3, "Organophosphates", "A farm worker sprayed with pesticide is drooling, wheezing and has pinpoint pupils. What is in AEMT scope?",
      ["Antidote auto-injector", "IV atropine titration", "Nebulized albuterol only", "Oral activated charcoal"],
      "The scope model lets every level use auto-injector antidotes for chemical exposures. Titrating IV atropine is a paramedic skill, and albuterol does not reverse the excess secretions."),
    S(1, 2, "Heat stroke", "A runner is confused and hot after a race, temperature 41.2 C. What is the priority?",
      ["Rapid cooling", "Oral sports drink", "Shade and rest first", "Wrap him in a blanket"],
      "Altered mental status with a high core temperature is heat stroke, and cooling quickly, ideally by cold water immersion, is the treatment that saves the brain. Oral fluids are unsafe in a confused patient."),
    S(1, 2, "Severe hypothermia", "A hypothermic patient with a slow pulse is found in snow. How should he be moved?",
      ["Gently and kept level", "Quickly, walking him out", "With his legs rubbed for warmth", "Sitting upright"],
      "A very cold heart is irritable, and rough handling can trigger ventricular fibrillation. Move the patient gently and horizontally and do not rub the limbs."),
    S(1, 3, "Breech birth", "During a breech birth the body has delivered, but the head has not. What should you do?",
      ["Make an air space with a V of fingers", "Pull firmly on the baby's legs", "Push the body back inside", "Wait for the next hour"],
      "NASEMSO has you place a gloved hand in the vagina with two fingers forming a V on either side of the baby's face to keep an air space, while you prepare for rapid transport. Never pull on the body."),
    S(1, 3, "Shoulder dystocia", "The head has delivered but the body will not follow with pushing. What should you try first?",
      ["Flex her hips sharply to her chest", "Pull down hard on the head", "Push on the top of the belly", "Have her stand and walk"],
      "Shoulder dystocia is treated by hyperflexing the mother's hips (McRoberts maneuver), with firm pressure just above the pubic bone if needed. Never pull on the head or push on the fundus."),
    # ---------- Practice Test 2 ----------
    O(2, 2, "IV setup", "Place the steps for preparing an IV bag and tubing in order.",
      ["Check fluid, clarity and expiry", "Close the roller clamp", "Spike the bag", "Squeeze to fill the drip chamber", "Run fluid to clear the tubing"],
      "Check the bag first, close the clamp so fluid does not run out when you spike, fill the drip chamber about halfway, then flush the line to clear air before it goes near the patient."),
    N(2, 3, "Mean arterial pressure", "A patient with suspected sepsis has a BP of 96/60. What is the MAP, in mm Hg?",
      72,
      "NASEMSO calculates MAP as (2 x diastolic + systolic) / 3: (120 + 96) / 3 = 72 mm Hg, above the 65 target for septic shock."),
    M(2, 2, "Preeclampsia", "A woman 34 weeks pregnant has a BP of 168/112. Which findings suggest severe preeclampsia? Select three.",
      ["Severe headache", "Spots in her vision", "Pain under the right ribs", "Heart rate of 58", "Glucose of 60", "Low-grade fever"],
      "Headache, visual changes and right upper quadrant pain with high blood pressure point to severe preeclampsia, which can progress to seizures. A slow pulse, borderline glucose and mild fever do not."),
    M(2, 3, "AEMT IV medications", "Which drugs does the national scope model allow AEMTs to give IV? Select two.",
      ["Dextrose", "Naloxone", "Amiodarone", "Midazolam", "Adenosine"],
      "The scope model limits AEMT IV drugs to analgesia, antiemetics, dextrose, epinephrine, glucagon, naloxone and others set by state protocol. Amiodarone, midazolam and adenosine are paramedic drugs."),
    S(2, 2, "Newborn resuscitation", "A newborn is dried and stimulated but his heart rate is 80. What next?",
      ["Start BVM ventilation", "Begin chest compressions", "Give blow-by oxygen only", "Keep rubbing his back"],
      "A heart rate under 100 after drying and stimulation means the baby needs positive pressure ventilation. Compressions start only if the rate stays under 60 despite good ventilation."),
    S(2, 2, "Newborn compressions", "During newborn resuscitation, what ratio of compressions to breaths is used?",
      ["3 to 1", "15 to 2", "30 to 2", "5 to 1"],
      "Newborns get coordinated compressions and breaths at 3:1, since their arrests are almost always from lack of oxygen. 15:2 is for two-rescuer child CPR and 30:2 for adults."),
    S(2, 3, "Prolapsed cord", "During labor the cord is seen in the vagina ahead of the baby. What should you do?",
      ["Hold the baby off the cord", "Push the cord back in", "Have her push hard", "Clamp the cord twice"],
      "With a gloved hand, hold the baby's presenting part off the cord to keep blood flowing, cover the cord with moist sterile gauze, and raise her hips or use knee-chest position during rapid transport."),
    S(2, 2, "Miscarriage", "A woman bleeding early in pregnancy has passed tissue. What should you do with it?",
      ["Bring it to the hospital", "Discard it at the scene", "Ask her to flush it", "Leave it with the family"],
      "Tissue passed during a miscarriage is placed in a container or bag and brought with her so the hospital can examine it. Treat her for blood loss and offer emotional support."),
    S(2, 3, "Placental abruption", "Late in pregnancy, which finding points to placental abruption rather than previa?",
      ["Painful, rigid uterus", "Painless bright red bleeding", "Bleeding after sex only", "Soft, non-tender uterus"],
      "Abruption, where the placenta tears away from the wall, causes pain and a tense uterus, and bleeding may be hidden. Placenta previa typically bleeds bright red without pain."),
    S(2, 2, "Eclampsia", "A pregnant woman with high BP has a seizure. Which drug treats eclamptic seizures, given by ALS?",
      ["Magnesium sulfate", "Oral glucose gel", "Naloxone", "Nitroglycerin spray"],
      "Magnesium sulfate treats and prevents eclamptic seizures and is a paramedic-level drug. The AEMT protects her from injury, positions her on her left side and gets ALS en route."),
    S(2, 2, "Diabetic ketoacidosis", "Which finding fits diabetic ketoacidosis?",
      ["Deep, rapid breathing", "Slow, shallow breathing", "Pinpoint pupils", "Cool, sweaty skin"],
      "In DKA the body blows off acid as CO2 with deep, rapid Kussmaul breaths, often with fruity breath and dehydration. Cool, sweaty skin is more typical of low blood sugar."),
    S(2, 2, "Antiemetics", "Which drug is used for nausea and vomiting within AEMT protocols?",
      ["Ondansetron", "Diphenhydramine", "Aspirin", "Albuterol"],
      "Ondansetron is an antiemetic, a class the scope model lets AEMTs give IV by protocol. NASEMSO avoids it in patients with a known prolonged QT interval."),
    S(2, 3, "Nitrous oxide", "A self-administered nitrous oxide mask would be unsafe for which patient?",
      ["Possible pneumothorax", "Ankle fracture, alert and calm", "Kidney stone pain, alert", "Shoulder dislocation, alert"],
      "Nitrous oxide expands into trapped air spaces, so a possible pneumothorax or bowel obstruction rules it out. Alert patients with painful injuries who can hold the mask are the usual candidates."),
    S(2, 2, "GI bleeding", "A patient vomits dark material that looks like coffee grounds. What does it suggest?",
      ["Upper GI bleeding", "Food poisoning", "A bowel obstruction", "A kidney stone"],
      "Blood that sits in the stomach turns dark and grainy, so coffee-ground vomit points to bleeding in the upper GI tract. Watch for signs of shock and save a description."),
    S(2, 2, "Carbon monoxide", "A patient from a house fire has a headache and an SpO2 of 99 percent. What oxygen does she need?",
      ["High flow oxygen", "None, since SpO2 is normal", "Nasal cannula at 2 L/min", "Titrate to 94 percent"],
      "NASEMSO gives high-flow oxygen to everyone rescued from an enclosed space fire. A normal SpO2 can hide carbon monoxide, and high oxygen speeds its removal."),
    S(2, 2, "Restraint", "When a violent patient must be physically restrained, which position must never be used?",
      ["Face down on the stretcher", "Supine with all four limbs held", "On the side with straps across", "Seated with the head up"],
      "Prone, face down or hog-tied restraint can stop a patient from breathing and has caused deaths. Restrain supine or on the side and watch breathing closely."),
    S(2, 2, "Envenomation", "A hiker was bitten on the ankle by a rattlesnake. What is right?",
      ["Keep the leg still", "Apply ice to the bite", "Tie a band above the bite", "Cut and suction the wound"],
      "NASEMSO forbids tourniquets, constricting bands, incision, suction and ice for envenomation. Keep the limb still, remove rings and tight items and transport to a center with antivenom."),
    S(2, 2, "Drowning", "A swimmer pulled from a pool is pulseless. What does resuscitation emphasize?",
      ["Early ventilation", "Abdominal thrusts first", "Shock before compressions", "Rewarming before CPR"],
      "Drowning arrests come from lack of oxygen, so early rescue breaths are central along with compressions. Abdominal thrusts delay CPR and do not remove water from the lungs."),
    S(2, 3, "Intoxication mimics", "A man who smells of alcohol is found confused on a sidewalk. Why not assume he is just drunk?",
      ["Low sugar or a head injury can mimic it", "Alcohol never causes confusion", "Drunk patients cannot refuse care", "Smell proves he drank recently"],
      "Hypoglycemia, a head injury, a stroke or an overdose can all look like intoxication, and alcohol makes them easier to miss. Check glucose, look for trauma and assess fully."),
    S(2, 1, "Seizure care", "A man is in the middle of a generalized seizure on a tile floor. What should you do?",
      ["Move hard objects away from him", "Put a bite block between his teeth", "Hold his arms and legs still", "Give oral glucose gel"],
      "Protect him from injury and time the seizure. Nothing goes in the mouth, holding the limbs can cause fractures, and oral glucose is unsafe while he is seizing."),
    # ---------- Drill only ----------
    X(0, 2, "Glucose route", "Each adult has a glucose under 60 mg/dL. Specify the right treatment route.",
      ["Alert and swallowing on command", "Unresponsive, no IV possible", "Seizing on the floor", "Confused but can sip and swallow"],
      ["Oral glucose", "IV dextrose or IM glucagon"], [0, 1, 1, 0],
      "Oral glucose is for a conscious patient with a patent airway. A patient who is unresponsive or seizing needs IV dextrose, or IM or IN glucagon when no IV can be placed."),
    O(0, 2, "IV start", "Place the steps for starting a peripheral IV in order.",
      ["Apply the tourniquet; pick a vein", "Clean the site", "Insert bevel up; watch for flash", "Advance the catheter; release tourniquet", "Connect tubing; check the flow"],
      "Find the vein under a tourniquet, prepare the skin, enter bevel up until blood flashes, slide the catheter in and release the tourniquet before removing the needle, then connect and confirm free flow."),
    N(0, 3, "Drip rate", "You must give 300 mL over 60 minutes with a 10 drop/mL set. How many drops per minute?",
      50,
      "Drops per minute = volume x drop factor / minutes: 300 x 10 / 60 = 50 drops per minute."),
    S(0, 2, "IV infiltration", "The skin around an IV site is swollen, cool and pale, and the drip has slowed. What should you do?",
      ["Stop it; restart elsewhere", "Raise the bag higher", "Flush the line hard", "Speed up the drip"],
      "Swelling, coolness and pallor show the fluid is going into the tissue. Stop the infusion, remove the catheter and start a new line in another site; flushing pushes more fluid out of the vein."),
    S(0, 3, "Fluid overload", "After 2 L of saline an older patient has new crackles and worse breathing. What do you suspect?",
      ["Circulatory overload", "An allergic reaction", "Air embolism", "Infiltration"],
      "Crackles and rising distress after large volumes show fluid backing up into the lungs. Slow the IV to keep-open, sit the patient up and report it."),
    S(0, 2, "IO access", "Which finding rules out the proximal tibia as an IO site?",
      ["Fracture of that tibia", "Shock with no IV veins", "An adult patient", "Cardiac arrest"],
      "IO needles are not placed in a fractured bone, a site with infection, or a bone with a recent IO attempt, because fluid leaks out. Shock and arrest with no IV access are why IO is used."),
    S(0, 2, "Glucagon", "When is IM glucagon the best choice for a hypoglycemic adult?",
      ["When no IV can be placed", "When glucose is above 100 mg/dL", "When the patient can eat a meal", "Before any glucose check"],
      "NASEMSO uses glucagon 1 mg IM or IN when an IV cannot be started. A patient who can swallow gets oral glucose, and treatment follows a glucose check."),
    S(0, 3, "Insulin pump", "An altered patient with an insulin pump has a glucose of 38. ALS is far away and he cannot swallow. What about the pump?",
      ["Stop or disconnect it", "Leave it running", "Turn the rate up", "Raise the basal rate slightly"],
      "NASEMSO stops, disconnects or removes the pump when the patient cannot take oral glucose and ALS is not available, so it stops delivering insulin. A patient who can eat keeps it running."),
    S(0, 2, "Anaphylactic shock", "After IM epinephrine, a patient with anaphylaxis still has a BP of 80/50. What should be added?",
      ["A 20 mL/kg fluid bolus", "Oral diphenhydramine", "Nitroglycerin", "Nothing for 30 minutes"],
      "NASEMSO adds 20 mL/kg of isotonic fluid given rapidly for poor perfusion in anaphylaxis and repeats IM epinephrine every 5 to 15 minutes."),
    S(0, 2, "Abdominal pain", "A woman of childbearing age has lower abdominal pain. Which question is most important early?",
      ["Date of her last period", "Her favorite foods", "Her blood type", "Time of her last workout"],
      "Any woman who could be pregnant with abdominal pain may have an ectopic pregnancy, so the last menstrual period guides the assessment."),
    S(0, 3, "Sickle cell crisis", "A teen with sickle cell disease has pain. Which finding is most urgent?",
      ["Chest pain, fever and low SpO2", "Aching knees and elbows", "Pain like his usual crises", "Mild yellowing of the eyes"],
      "Chest pain with fever, cough or low oxygen in sickle cell disease suggests acute chest syndrome, a leading cause of death in these patients. Joint pain is the common crisis."),
    S(0, 2, "Hypothermia", "A mildly hypothermic hiker is shivering and alert. What helps first?",
      ["Remove wet clothes", "Have him exercise to warm", "Give a hot alcoholic drink", "Rub his arms and legs"],
      "Remove wet clothing, dry him and wrap him in blankets in a warm space. Alcohol widens vessels and speeds heat loss, and exertion or rubbing can stress a cold heart."),
    S(0, 2, "Heat exhaustion", "Which finding separates heat stroke from heat exhaustion?",
      ["Altered mental status", "Heavy sweating", "Muscle cramps", "Thirst, fatigue and headache"],
      "Confusion, seizures or unresponsiveness with a high temperature mark heat stroke. Sweating, cramps and fatigue occur in heat exhaustion, and some heat stroke patients still sweat."),
    S(0, 1, "Newborn care", "Right after birth a newborn is breathing and crying. What comes next?",
      ["Dry and warm the baby", "Suction deeply", "Give blow-by oxygen", "Hold him upside down"],
      "Newborns lose heat fast, so dry, warm and keep them skin to skin. Routine deep suctioning is not needed for a baby who is breathing and crying."),
]
